  "knowledge": "Aggressive Event Speculator",
  "description": "Classifies event-driven traders who employ an aggressive risk strategy.",
  "definition": "A trader classified as an Event-Driven Trader  AND whose Trader Risk Appetite  is 'Aggressive'."
}

{
  "id": 28,
  "knowledge": "Pattern Similarity Score Context",
  "description": "Provides context for the pattern similarity score, comparing trading to known illicit behaviors.",
  "definition": "`patsim`: A score typically ranging from 0 to 1. Values close to 1 indicate a high similarity to known illicit trading patterns cataloged by the surveillance system (e.g., layering, spoofing, wash trading). Values close to 0 indicate the observed trading patterns do not strongly match known manipulative techniques."
}

{
  "id": 30,
  "knowledge": "Risk-Adjusted Turnover (RAT)",
  "description": "Calculates trader turnover scaled by their leverage exposure.",
  "definition": "RAT = \\text{DTR} \\times \\text{TLE} \\\\ \\text{where DTR is Daily Turnover Rate  and TLE is Trader Leverage Exposure .}"
}

{
  "id": 31,
  "knowledge": "Combined Manipulation Indicator (CMI)",
  "description": "A combined score reflecting both general suspicious activity and specific pattern anomalies.",
  "definition": "CMI = (\\text{SAI} + \\text{PAS}) / 2 \\\\ \\text{where SAI is Suspicious Activity Index  and PAS is Pattern Anomaly Score .}"
}

{
  "id": 4,
  "knowledge": "Pattern Anomaly Score (PAS)",
  "description": "Measures the deviation of a trader's pattern similarity from their peer correlation, potentially indicating unique illicit behavior.",
  "definition": "PAS = |\\text{patsim} - \\text{peercorr}|"
}

{
  "id": 56,
  "knowledge": "Market-Agnostic Suspicion Index (MASI)",
  "description": "Combines the general suspicion index with market-adjusted pattern anomaly, focusing on suspicious activity independent of market moves.",
  "definition": "MASI = (\\text{SAI} + \\text{MAPA}) / 2 \\\\ \\text{where SAI is Suspicious Activity Index  and MAPA is Market-Adjusted Pattern Anomaly .}"
}

{
  "id": 39,
  "knowledge": "Market-Adjusted Pattern Anomaly (MAPA)",
  "description": "Calculates pattern anomaly score adjusted for market correlation, highlighting non-market related deviations.",
  "definition": "MAPA = \\text{PAS} \\times (1 - \\text{mktcorr}) \\\\ \\text{where PAS is Pattern Anomaly Score .}"
}

{
  "id": 37,
  "knowledge": "Suspicion-Weighted Turnover (SWT)",
  "description": "Calculates daily turnover weighted by the Suspicious Activity Index.",
  "definition": "SWT = \\text{SAI} \\times \\text{DTR} \\\\ \\text{where SAI is Suspicious Activity Index  and DTR is Daily Turnover Rate .}"
}

